{
  "event_id": "E216",
  "summary": "The event, starting on May 10, 2024, and lasting for 143 hours, was a super geomagnetic storm with aDst minimum of -406 nT. The storm was associated with a southward Bz magnetic field and fast solar wind, which could have caused significant impacts on the Earth's magnetosphere and ionosphere, leading to potential disruptions in radio communications and satellite operations.",
  "characteristics": [
    {
      "statement": "Dst minimum of -406 nT",
      "evidence": ["dst.min_nT"]
    },
    {
      "statement": "Sustained southward Bz (23 hours at or below -5 nT, minimum hourly Bz -39.3 nT)",
      "evidence": ["drivers.bz_min_hourly_nT", "drivers.bz_min_time", "geomagnetic.kp_max"]
    },
    {
      "statement": "Very fast solar wind (maximum hourly speed 1006 km/s)",
      "evidence": ["drivers.speed_max_km_per_s"]
    },
    {
      "statement": "Strong solar wind dynamic pressure (up to 42.0 nPa (protons only))",
      "evidence": ["drivers.dynamic_pressure_max_nPa_protons_only"]
    }
  ],
  "possible_physical_interpretation": [
    {
      "statement": "Southward Bz is the main way solar wind energy enters the magnetosphere, leading to significant geomagnetic activity.",
      "sources": ["d03_c004", "d03_c000"]
    }
  ],
  "potential_impacts": [
    {
      "area": "satellites and spacecraft",
      "statement": "Increased drag on satellites in low-Earth orbit could have caused orbit changes.",
      "sources": ["d15_c003", "d11_c002"]
    },
    {
      "area": "power systems",
      "statement": "Geoelectric fields could have caused geomagnetically induced currents in power lines, potentially leading to system-wide blackouts or transformer saturation.",
      "sources": ["d07_c006", "d07_c008"]
    },
    {
      "area": "HF radio",
      "statement": "HF radio communications could have been disrupted, especially at high latitudes.",
      "sources": ["d14_c001", "d14_c002"]
    },
    {
      "area": "GNSS navigation",
      "statement": "GPS signals could have been disrupted, affecting positioning accuracy.",
      "sources": ["d03_c004"]
    },
    {
      "area": "aurora",
      "statement": "Auroral displays were observed at lower latitudes than usual, potentially affecting low-latitude observatories and agricultural operations.",
      "sources": ["d13_c004", "d13_c009", "d12_c109"]
    },
    {
      "area": "aurora",
      "statement": "Auroral altitudes could have been observed at lower latitudes due to the storm's intensity.",
      "sources": ["d13_c009"]
    }
  ],
  "caveats": [
    "Dst is provisional and may be revised by Kyoto.",
    "Solar wind and magnetic field values are shifted to the time they reach Earth (a delay of roughly 25 to 100 minutes depending on solar wind speed).",
    "Only 29% of the solar wind plasma hours come from DSCOVR; the rest are OMNI hourly values because DSCOVR plasma was flagged as unreliable or missing."
  ],
  "unsupported_or_unknown": [
    "physical cause of the event (for example a coronal mass ejection or a high-speed stream): no supporting source",
    "impacts on satellites, GNSS, radio communication, power grids or aurora: no supporting source",
    "comparison with, or ranking against, other historical storms: no supporting source",
    "any forecast or prediction: no supporting source"
  ]
}
